from candidate import same_chars
import unittest
from unittest.mock import patch

class TestSameChars(unittest.TestCase):

    def test_same_chars_with_identical_strings(self):
        self.assertTrue(same_chars('eabcdzzzz', 'dddzzzzzzzddeddabc'))

    def test_same_chars_with_identical_sorted_characters(self):
        self.assertTrue(same_chars('abcd', 'dddddddabc'))

    def test_same_chars_with_different_order(self):
        self.assertTrue(same_chars('dddddddabc', 'abcd'))

    def test_same_chars_with_different_characters(self):
        self.assertFalse(same_chars('eabcd', 'dddddddabce'))

    def test_same_chars_with_extra_characters(self):
        self.assertFalse(same_chars('eabcdzzzz', 'dddzzzzzzzddddabc'))

    @patch('builtins.open', new_callable=patch.dict)
    def test_same_chars_with_file_input(self, mock_file):
        with mock_file('test.txt', 'dddzzzzzzzddddabc', 'r') as file:
            self.assertTrue(same_chars(file.read(), 'eabcdzzzz'))

    def test_same_chars_with_empty_strings(self):
        self.assertTrue(same_chars('', ''))

    def test_same_chars_with_none(self):
        with patch('builtins.open', new_callable=patch.dict):
            with self.assertRaises(TypeError):
                same_chars(None, 'abc')

    def test_same_chars_with_non_string_input(self):
        with self.assertRaises(TypeError):
            same_chars(123, 'abc')

if __name__ == '__main__':
    unittest.main()
